/*
 * Title:        São João del-Rei Tourist AR - TaskProperty
 *
 * Description:
 * Stores the properties of tasks generated by the tourist
 * Augmented Reality application.
 *
 * The task type identifies the kind of application data and
 * is subsequently used by the workload generator, mobile
 * device manager and edge orchestrator to determine the
 * appropriate processing and communication path.
 *
 * Application data types:
 *
 * 0 - AR_CONTENT
 *     Multimedia content associated with a tourist attraction.
 *     Main flow: Edge -> Mobile
 *
 * 1 - TRANSPORT
 *     Dynamic information, such as the next bus to another
 *     attraction.
 *     Main flow: Cloud -> Mobile
 *
 * 2 - VISITOR_COUNT
 *     Number of visitors currently associated with an attraction.
 *     Main flow: Mobile -> Edge -> Cloud
 *
 * 3 - TICKET
 *     Centralized information, such as ticket availability.
 *     Main flow: Mobile -> Cloud
 *
 * 4 - INTERACTION
 *     Interaction generated during the augmented reality
 *     experience.
 *     Main flow: Mobile -> Edge -> Mobile
 *
 * Licence:      GPL - http://www.gnu.org/copyleft/gpl.html
 * Copyright (c) 2017, Bogazici University, Istanbul, Turkey
 */

package edu.boun.edgecloudsim.utils;

import org.apache.commons.math3.distribution.ExponentialDistribution;

import edu.boun.edgecloudsim.core.SimSettings;


/**
 * Represents the characteristics of a task generated by a
 * mobile tourist device.
 *
 * TaskProperty is used by the workload generator before the
 * task is converted into an EdgeCloudSim Task object.
 *
 * Besides computational characteristics, this class explicitly
 * identifies the application data type. This information allows
 * the orchestration layer to differentiate the communication
 * and processing requirements of the tourist application.
 */
public class TaskProperty {


    /*
     * ============================================================
     * APPLICATION DATA TYPES
     * ============================================================
     *
     * The values are zero-based because taskType is also used
     * as an index in EdgeCloudSim configuration structures,
     * such as the task lookup table.
     */

    /**
     * Multimedia content associated with the attraction.
     *
     * Examples:
     * - 3D models
     * - images
     * - videos
     * - audio
     * - textual descriptions
     *
     * Main communication path:
     *
     * Edge -> Mobile
     */
    public static final int AR_CONTENT = 0;


    /**
     * Dynamic transportation information.
     *
     * Examples:
     * - next bus
     * - estimated departure time
     * - transportation availability
     *
     * Main communication path:
     *
     * Cloud -> Mobile
     */
    public static final int TRANSPORT = 1;


    /**
     * Number of visitors associated with an attraction.
     *
     * The information is initially processed at the Edge and
     * subsequently synchronized with the Cloud.
     *
     * Main communication path:
     *
     * Mobile -> Edge -> Cloud
     */
    public static final int VISITOR_COUNT = 2;


    /**
     * Centralized ticket information.
     *
     * Examples:
     * - number of available tickets
     * - ticket availability
     * - ticket status
     *
     * Main communication path:
     *
     * Mobile -> Cloud
     */
    public static final int TICKET = 3;


    /**
     * Interaction generated during the AR experience.
     *
     * Examples:
     * - interaction with a 3D object
     * - selection of an historical element
     * - request for additional local information
     *
     * Main communication path:
     *
     * Mobile -> Edge -> Mobile
     */
    public static final int INTERACTION = 4;


    /**
     * Number of application data types.
     */
    public static final int NUMBER_OF_DATA_TYPES = 5;


    /*
     * ============================================================
     * TASK ATTRIBUTES
     * ============================================================
     */

    /**
     * Simulation time when the task is generated.
     *
     * Unit: seconds.
     */
    private double startTime;


    /**
     * Computational requirement of the task.
     *
     * Unit: Million Instructions (MI).
     */
    private long length;


    /**
     * Amount of data transmitted from the mobile device
     * to the processing node.
     *
     * Unit: bytes.
     */
    private long inputFileSize;


    /**
     * Amount of data transmitted from the processing node
     * to the mobile device.
     *
     * Unit: bytes.
     */
    private long outputFileSize;


    /**
     * Application data type.
     *
     * Values:
     *
     * AR_CONTENT     = 0
     * TRANSPORT      = 1
     * VISITOR_COUNT  = 2
     * TICKET         = 3
     * INTERACTION    = 4
     */
    private int taskType;


    /**
     * Number of processing elements required by the task.
     */
    private int pesNumber;


    /**
     * Identifier of the mobile device generating the task.
     */
    private int mobileDeviceId;


    /*
     * ============================================================
     * EXPLICIT CONSTRUCTOR
     * ============================================================
     *
     * This constructor is useful when the application workload
     * explicitly defines the characteristics of each task.
     */

    /**
     * Creates a task with explicitly defined characteristics.
     *
     * @param _startTime simulation time of task generation
     * @param _mobileDeviceId mobile device generating the task
     * @param _taskType application data type
     * @param _pesNumber number of required CPU cores
     * @param _length computational requirement in MI
     * @param _inputFileSize input data size in bytes
     * @param _outputFileSize output data size in bytes
     */
    public TaskProperty(
            double _startTime,
            int _mobileDeviceId,
            int _taskType,
            int _pesNumber,
            long _length,
            long _inputFileSize,
            long _outputFileSize) {


        /*
         * Validate the application data type before storing it.
         */

        validateTaskType(_taskType);


        startTime = _startTime;

        mobileDeviceId = _mobileDeviceId;

        taskType = _taskType;

        pesNumber = _pesNumber;

        length = _length;

        inputFileSize = _inputFileSize;

        outputFileSize = _outputFileSize;
    }


    /*
     * ============================================================
     * DISTRIBUTION-BASED CONSTRUCTOR
     * ============================================================
     *
     * This constructor is compatible with the original
     * EdgeCloudSim workload generation mechanism.
     *
     * The characteristics of a task are sampled from
     * exponential distributions according to its task type.
     *
     * expRngList[taskType][0] -> input data
     * expRngList[taskType][1] -> output data
     * expRngList[taskType][2] -> computational length
     */

    /**
     * Creates a task using statistical distributions.
     *
     * @param _mobileDeviceId mobile device generating the task
     * @param _taskType application data type
     * @param _startTime task generation time
     * @param expRngList exponential distributions indexed by
     *                  task type and characteristic
     */
    public TaskProperty(
            int _mobileDeviceId,
            int _taskType,
            double _startTime,
            ExponentialDistribution[][] expRngList) {


        /*
         * Validate task type.
         */

        validateTaskType(_taskType);


        /*
         * Validate distribution structure.
         */

        if (expRngList == null) {

            throw new IllegalArgumentException(
                "Task distribution list cannot be null."
            );
        }


        if (_taskType >= expRngList.length) {

            throw new IllegalArgumentException(
                "No distribution is available for task type "
                + _taskType
            );
        }


        if (
            expRngList[_taskType] == null
            ||
            expRngList[_taskType].length < 3
        ) {

            throw new IllegalArgumentException(
                "Invalid distribution definition for task type "
                + _taskType
            );
        }


        /*
         * Store basic attributes.
         */

        mobileDeviceId = _mobileDeviceId;

        taskType = _taskType;

        startTime = _startTime;


        /*
         * Generate task characteristics.
         */

        inputFileSize =
                (long) expRngList[_taskType][0].sample();


        outputFileSize =
                (long) expRngList[_taskType][1].sample();


        length =
                (long) expRngList[_taskType][2].sample();


        /*
         * Retrieve the number of required CPU cores from
         * the EdgeCloudSim task configuration.
         */

        pesNumber =
                (int) SimSettings
                        .getInstance()
                        .getTaskLookUpTable()[_taskType][8];
    }


    /*
     * ============================================================
     * HOMOGENEOUS WORKLOAD CONSTRUCTOR
     * ============================================================
     *
     * The original EdgeCloudSim constructor assumes task type 0.
     *
     * In the SJR application, type 0 corresponds to AR_CONTENT.
     *
     * This constructor is therefore retained for compatibility
     * with workload generators that create a homogeneous workload.
     */

    /**
     * Creates a homogeneous AR_CONTENT task using
     * exponential distributions.
     *
     * @param mobileDeviceId mobile device generating the task
     * @param startTime task generation time
     * @param expRngList distributions for input, output and
     *                   computational requirements
     */
    public TaskProperty(
            int mobileDeviceId,
            double startTime,
            ExponentialDistribution[] expRngList) {


        /*
         * Validate distribution structure.
         */

        if (expRngList == null) {

            throw new IllegalArgumentException(
                "Task distribution list cannot be null."
            );
        }


        if (expRngList.length < 3) {

            throw new IllegalArgumentException(
                "At least three distributions are required."
            );
        }


        /*
         * Type 0 is AR_CONTENT.
         */

        taskType = AR_CONTENT;


        mobileDeviceId = mobileDeviceId;

        this.mobileDeviceId = mobileDeviceId;

        this.startTime = startTime;


        /*
         * Generate task characteristics.
         */

        inputFileSize =
                (long) expRngList[0].sample();


        outputFileSize =
                (long) expRngList[1].sample();


        length =
                (long) expRngList[2].sample();


        /*
         * Retrieve CPU requirement for AR_CONTENT.
         */

        pesNumber =
                (int) SimSettings
                        .getInstance()
                        .getTaskLookUpTable()[AR_CONTENT][8];
    }


    /*
     * ============================================================
     * GETTERS
     * ============================================================
     */

    /**
     * Returns the task generation time.
     *
     * @return task generation time in seconds
     */
    public double getStartTime() {

        return startTime;
    }


    /**
     * Returns the computational requirement.
     *
     * @return task length in MI
     */
    public long getLength() {

        return length;
    }


    /**
     * Returns the input data size.
     *
     * @return input data size in bytes
     */
    public long getInputFileSize() {

        return inputFileSize;
    }


    /**
     * Returns the output data size.
     *
     * @return output data size in bytes
     */
    public long getOutputFileSize() {

        return outputFileSize;
    }


    /**
     * Returns the application data type.
     *
     * @return task type
     */
    public int getTaskType() {

        return taskType;
    }


    /**
     * Returns the number of processing elements required.
     *
     * @return required CPU cores
     */
    public int getPesNumber() {

        return pesNumber;
    }


    /**
     * Returns the originating mobile device.
     *
     * @return mobile device identifier
     */
    public int getMobileDeviceId() {

        return mobileDeviceId;
    }


    /*
     * ============================================================
     * DATA TYPE HELPERS
     * ============================================================
     *
     * These methods centralize the semantic interpretation of
     * task types.
     *
     * They can subsequently be used by the orchestrator and
     * MobileDeviceManager.
     */


    /**
     * Returns the textual name of an application data type.
     *
     * @param taskType application data type
     * @return textual representation
     */
    public static String getTaskTypeName(
            int taskType) {


        switch (taskType) {


            case AR_CONTENT:

                return "AR_CONTENT";


            case TRANSPORT:

                return "TRANSPORT";


            case VISITOR_COUNT:

                return "VISITOR_COUNT";


            case TICKET:

                return "TICKET";


            case INTERACTION:

                return "INTERACTION";


            default:

                return "UNKNOWN";
        }
    }


    /**
     * Determines whether the task is primarily associated
     * with Edge processing.
     *
     * AR_CONTENT:
     *     Edge -> Mobile
     *
     * VISITOR_COUNT:
     *     Mobile -> Edge -> Cloud
     *
     * INTERACTION:
     *     Mobile -> Edge -> Mobile
     *
     * @param taskType application data type
     * @return true when Edge processing is appropriate
     */
    public static boolean isEdgeTask(
            int taskType) {


        return
            taskType == AR_CONTENT
            ||
            taskType == VISITOR_COUNT
            ||
            taskType == INTERACTION;
    }


    /**
     * Determines whether the task is primarily associated
     * with Cloud processing.
     *
     * TRANSPORT:
     *     Cloud -> Mobile
     *
     * TICKET:
     *     Mobile -> Cloud
     *
     * @param taskType application data type
     * @return true when Cloud processing is appropriate
     */
    public static boolean isCloudTask(
            int taskType) {


        return
            taskType == TRANSPORT
            ||
            taskType == TICKET;
    }


    /**
     * Determines whether the task must be synchronized
     * from Edge to Cloud after local processing.
     *
     * @param taskType application data type
     * @return true for VISITOR_COUNT
     */
    public static boolean requiresCloudSynchronization(
            int taskType) {


        return taskType == VISITOR_COUNT;
    }


    /**
     * Determines whether the task represents information
     * downloaded from infrastructure to the tourist device.
     *
     * @param taskType application data type
     * @return true for AR_CONTENT and TRANSPORT
     */
    public static boolean isDownloadTask(
            int taskType) {


        return
            taskType == AR_CONTENT
            ||
            taskType == TRANSPORT;
    }


    /**
     * Determines whether the task represents information
     * uploaded by the tourist device.
     *
     * @param taskType application data type
     * @return true for VISITOR_COUNT and TICKET
     */
    public static boolean isUploadTask(
            int taskType) {


        return
            taskType == VISITOR_COUNT
            ||
            taskType == TICKET;
    }


    /*
     * ============================================================
     * VALIDATION
     * ============================================================
     */

    /**
     * Validates an application data type.
     *
     * @param taskType task type to validate
     */
    private static void validateTaskType(
            int taskType) {


        if (
            taskType < 0
            ||
            taskType >= NUMBER_OF_DATA_TYPES
        ) {


            throw new IllegalArgumentException(
                "Invalid task type: "
                + taskType
                + ". Valid values are 0 to "
                + (NUMBER_OF_DATA_TYPES - 1)
                + "."
            );
        }
    }
}